 % The source (references/qpbt-paper/06_nonlocal_games_and_mipstar.tex:504-505) quantifies
 % the pairwise-agreement hypothesis over every pair (x, y_1), including pairs carrying
 % probability zero under D, on which no conditional distribution of y_2 is defined; the
 % hypothesis is restated here over the pairs of positive marginal probability, the only
 % pairs the sampling in the hypothesis can refer to and the only ones the averaged
 % conclusion depends on. The NEEXP original (references/neexp-paper/
 % 05_quantum_preliminaries.tex:1000-1008, label fact:low-degree-sandwich-on-steroids)
 % conditions on a fixed question tuple with the same restriction left implicit.
 \begin{lemma}[Pasting two consistent measurements; Fact 4.35 in \cite{Natarajan2018NEEXP}]\label{lem:pasting}
 	\lean{MIPStarRE.QPBT.pastedMeasurement}
 	\lean{MIPStarRE.QPBT.exists_pasting_error}
 	\leanok
 	\uses{def:consistency, def:bracket, def:povm-conventions}
 	Let $\mathcal D$ be a distribution on $(x, y_1, y_2) \in \mathcal X \times \mathcal Y_1 \times \mathcal Y_2$. For $i \in \{1,2\}$ let $\mathcal G_i$ be a collection of functions $g_i \colon \mathcal Y_i \to \mathcal R_i$ and let $\{(G_i)^x_g\}_{g \in \mathcal G_i}$ be families of measurements such that $\{(G_2)^x_g\}_g$ is projective for every $x$. Suppose further that for every pair $(x, y_1)$ of positive probability under the marginal of $\mathcal D$ on $\mathcal X \times \mathcal Y_1$ (the only pairs for which the conditional distribution of $y_2$ under $\mathcal D$ is defined; pairs of marginal probability zero are subject to no requirement) it holds that for $g_2 \ne g_2' \in \mathcal G_2$ the probability, on average over $y_2$ chosen from $\mathcal D$ conditioned on $(x, y_1)$, that $g_2(y_2) = g_2'(y_2)$ is at most $\eta$. Let $\{A^{x,y_1,y_2}_{a_1,\,a_2}\}$ be a family of projective measurements with outcomes $(a_1, a_2) \in \mathcal R_1 \times \mathcal R_2$ such that for $i \in \{1,2\}$,
 	\begin{equation}\label{eq:pasting-1}
 		A^{x,y_1,y_2}_{a_i} \ot \Id \simeq_\delta \Id \ot (G_i)^x_{[\operatorname{eval}_{y_i}(\cdot)=a_i]}
 	\end{equation}
 	and
 	\begin{equation}\label{eq:pasting-2}
 		A^{x,y_1,y_2}_{a_1,\,a_2} \ot \Id \simeq_\delta \Id \ot A^{x,y_1,y_2}_{a_1,\,a_2}\,,
 	\end{equation}
 	where $A^{x,y_1,y_2}_{a_i}$ denotes the marginal on the $i$-th part of the outcome (Definition~\ref{def:povm-conventions}). Define a family of measurements $\{J^x_{g_1,\,g_2}\}$ by
 	\begin{equation}\label{eq:pasting-2a}
 		J^x_{g_1,\,g_2} = (G_2)^x_{g_2}\, (G_1)^x_{g_1}\, (G_2)^x_{g_2}\,.
 	\end{equation}
 	Then there is a
 	\begin{equation}\label{eq:def-deltap}
 		\delta_{\mathrm{pasting}} = \delta_{\mathrm{pasting}}(\eta, \delta) = \poly(\eta, \delta)
 	\end{equation}
 	such that
 	\begin{equation}\label{eq:pasting-3}
 		A^{x,y_1,y_2}_{a_1,\,a_2} \ot \Id \simeq_{\delta_{\mathrm{pasting}}} \Id \ot J^x_{[\operatorname{eval}_{y_1}(\cdot)=a_1,\, \operatorname{eval}_{y_2}(\cdot)=a_2]}\,.
 	\end{equation}
 	Neither the exponent nor the constant in $\poly(\eta, \delta)$ is made explicit in the source; both are universal constants inherited from the proof of Fact 4.35 in \cite{Natarajan2018NEEXP}. The literal product-form convention for this notation is incompatible with the unrestricted error domain in the lemma; a two-dimensional counterexample and the required correction are recorded in \cite{gap:qpbt_pasting-product-error}.
 \end{lemma}
+\begin{proof}
+	\leanok
+	\uses{lem:pasting-forward-comparisons}
+	Apply Lemma~\ref{lem:pasting-forward-comparisons} to the two marginal
+	comparisons~\eqref{eq:pasting-1}. These suffice for the pasted conclusion;
+	the self-consistency comparison~\eqref{eq:pasting-2} is not needed.
+\end{proof}
+
+\begin{lemma}[Pasting from the forward comparisons]
+	\label{lem:pasting-forward-comparisons}
+	\lean{MIPStarRE.QPBT.exists_pasting_error_of_marginal_consistency}
+	\leanok
+	\uses{def:consistency, def:bracket, def:povm-conventions}
+	This formalization-only strengthening of Lemma~\ref{lem:pasting} has the
+	same conclusion under its projectivity and conditional collision hypotheses
+	and the two forward comparisons~\eqref{eq:pasting-1}, for a unit state and
+	$\eta,\delta\geq0$. The self-consistency comparison~\eqref{eq:pasting-2}
+	is not required. The local carrier is common to both players.
+\end{lemma}
 \begin{proof}
 	\leanok
 	\uses{lem:pasting-one-sided-explicit-error, lem:pasting-coarse-commutator,
 		lem:pasting-measurement, lem:pasting-scalar-error, lem:pasting-defect-bound}
 	Use the fixed Schmidt mirror of the second codeword family on Alice's
 	register. Its coarse consistency defect is at most $2\delta$ and its fine
 	defect at most $2\delta+\eta$. The distinct-family commutator comparison
 	then proves the conclusion without a register-exchange assumption.
 	For the universal coarse-commutator constant $C\geq1$, one may take
 	$\delta_{\mathrm{pasting}}=(3C+19)(\eta^{1/4}+\delta^{1/8})$.
 	On the unit square use Lemma~\ref{lem:pasting-scalar-error}; outside it,
 	this error is at least $1$, so Lemma~\ref{lem:pasting-defect-bound} applies.
 	Thus the polynomial notation here uses the additive correction documented
 	in \cite{gap:qpbt_pasting-product-error}, not the refuted product contract.
 \end{proof}

+\begin{definition}[Adjoining fixed basis vectors]
+	\label{def:pasting-product-state}
+	\lean{MIPStarRE.QPBT.Pasting.productPaddedState}
+	\leanok
+	Let $\mathcal H_A=\mathbb C^{I_A}$ and $\mathcal H_B=\mathbb C^{I_B}$,
+	where $I_A,I_B$ are finite, and fix $a_0\in I_A$, $b_0\in I_B$.
+	For $\psi\in\mathcal H_A\otimes\mathcal H_B$, define a vector on
+	$(\mathcal H_A\otimes\mathcal H_B)^{\otimes2}$ by
+	\[
+		\Psi_{(i,b),(a,j)}
+		=\mathbf 1_{b=b_0}\mathbf 1_{a=a_0}\psi_{i,j}.
+	\]
+	This is a formalization-only common-space realization for
+	Lemma~\ref{lem:pasting}.
+\end{definition}
+
+\begin{lemma}[Preservation under adjoining basis vectors]
+	\label{lem:pasting-product-state-preservation}
+	\lean{MIPStarRE.QPBT.Pasting.productPaddedState_norm}
+	\lean{MIPStarRE.QPBT.Pasting.stateQForm_productPaddedState}
+	\lean{MIPStarRE.QPBT.Pasting.consistencyDefect_productPaddedState}
+	\leanok
+	\uses{def:pasting-product-state, def:consistency}
+	For the preceding construction, $\|\Psi\|=\|\psi\|$. For arbitrary
+	operators $A$ on $\mathcal H_A$ and $B$ on $\mathcal H_B$,
+	\[
+		\operatorname{Re}\langle\Psi,
+		 ((A\otimes\Id)\otimes(\Id\otimes B))\Psi\rangle
+		=\operatorname{Re}\langle\psi,(A\otimes B)\psi\rangle.
+	\]
+	Consequently every averaged off-diagonal consistency defect is preserved
+	by these local placements, for arbitrary operator families and any finite
+	distribution. Positivity and state normalization are not required.
+\end{lemma}
+\begin{proof}
+	\leanok
+	\uses{def:pasting-product-state}
+	Expand the norm and quadratic form in the standard bases. The fixed
+	coordinates remove two sums. Sum the quadratic-form identity over unequal
+	answers and average over the question distribution.
+\end{proof}
+
+\begin{lemma}[Pasting on independent local spaces]
+	\label{lem:pasting-heterogeneous}
+	\lean{MIPStarRE.QPBT.exists_pasting_error_heterogeneous}
+	\leanok
+	\uses{def:consistency, def:bracket, def:povm-conventions}
+	There is a universal function
+	$\delta_{\mathrm{pasting}}(\eta,\delta)=\poly(\eta,\delta)$ for which
+	Lemma~\ref{lem:pasting-forward-comparisons} holds with independent finite
+	local spaces $\mathcal H_A$ and $\mathcal H_B$. The family $A$ acts on
+	$\mathcal H_A$, the families $G_1,G_2$ act on $\mathcal H_B$, and the
+	unit state belongs to $\mathcal H_A\otimes\mathcal H_B$. All conditional
+	collision, projectivity, and forward comparison hypotheses, and the
+	conclusion~\eqref{eq:pasting-3}, are retained. This is a
+	formalization-only strengthening of Lemma~\ref{lem:pasting}.
+\end{lemma}
+\begin{proof}
+	\leanok
+	\uses{lem:pasting-forward-comparisons, lem:pasting-product-state-preservation,
+		lem:pasting-tensor-placement}
+	A unit state implies that both local spaces are nonzero. Choose one basis
+	vector in each and adjoin them as in Definition~\ref{def:pasting-product-state}.
+	The common local space is $\mathcal H_A\otimes\mathcal H_B$.
+	Tensor placement preserves projectivity, postprocessing, and the product
+	$G_2G_1G_2$. Both input defects and the pasted output defect are unchanged.
+	Apply Lemma~\ref{lem:pasting-forward-comparisons} on this common space.
+\end{proof}
+
 \begin{lemma}[Universal bound for placed consistency defects]
 	\label{lem:pasting-defect-bound}
 	\lean{MIPStarRE.QPBT.consistencyDefect_placed_le_one}
 	\leanok
 	\uses{def:consistency, def:povm-conventions}
 	Let $\mu$ be a probability law on a finite question set, let $A^x_a$ and
 	$B^x_a$ be measurements on the two tensor factors with the same finite
 	outcome set, and let $\psi$ be a unit vector. Then
 	\[
 		\E_{x\sim\mu}\sum_{a\ne b}
 		\langle\psi|A^x_a\ot B^x_b|\psi\rangle\leq1.
 	\]
 	This is formalization support for the complementary error regime of
 	Lemma~\ref{lem:pasting}; projectivity is not required.
 \end{lemma}
 \begin{proof}
 	\leanok
 	Completeness makes the sum over all outcome pairs equal to $1$.
 	Removing the nonnegative diagonal terms can only decrease it.
 \end{proof}

 \begin{lemma}[Scalar comparison for the pasting error]
 	\label{lem:pasting-scalar-error}
 	\lean{MIPStarRE.QPBT.pasting_error_sqrt_le_rpow}
 	\leanok
 	For $C\geq1$ and $0\leq\eta,\delta\leq1$, set
 	\[
 		K=C\delta+(2\sqrt{2\delta}+2\delta+2\sqrt{C\delta}+C\delta)
 		  +2\eta+2\sqrt{2(\delta+2\sqrt{2\delta}+\eta)}
 		  +2\sqrt{2(\delta+2\sqrt{2\delta})}.
 	\]
 	Then $2\delta+\sqrt K\leq(3C+19)(\eta^{1/4}+\delta^{1/8})$.
 	This is a formalization-only scalar estimate for Lemma~\ref{lem:pasting}.
 \end{lemma}
 \begin{proof}
 	\leanok
 	Put $u=\delta^{1/8}$ and $v=\eta^{1/4}$. Both lie in $[0,1]$.
 	Bound the successive square roots using these variables and compare
 	the resulting nonnegative polynomials.
 \end{proof}

 \begin{lemma}[Paired-entry estimate for the Schmidt mirror]
 	\label{lem:pasting-schmidt-pair}
 	\lean{MIPStarRE.QPBT.schmidt_pair_mirror_estimate}
 	\leanok
 	For $s,t\geq0$ and $u,v\in\mathbb C$,
 	\[
 		(s-t)^2|v|^2 \leq |tu-sv|^2+|su-tv|^2.
 	\]
 	This is a formalization-only auxiliary for the one-sided argument in
 	\cite{gap:qpbt_pasting-product-error}, not a named assertion of the paper.
 \end{lemma}
 \begin{proof}
 	\leanok
 	The difference between the right and left sides is
 	$(s-t)^2|u|^2+2st|u-v|^2\geq0$.
 \end{proof}

 \begin{lemma}[Schmidt coordinates for a square coefficient matrix]
 	\label{lem:pasting-schmidt-coordinates}
 	\lean{MIPStarRE.QPBT.exists_schmidt_coordinates, MIPStarRE.QPBT.schmidtCoordinates_spec}
 	\leanok
 	Every square complex matrix $C$ has a decomposition
 	$C=U\operatorname{diag}(s_i)V^*$ with unitary $U,V$ and $s_i\geq0$.
 	Zero singular values are allowed. This is a formalization-only construction
 	for the argument in \cite{gap:qpbt_pasting-product-error}.
 \end{lemma}
 \begin{proof}
 	\leanok
 	Diagonalize $C^*C$, normalize the images of its positive-eigenvalue
 	eigenvectors, and complete this orthonormal family on the left. The
 	zero-eigenvalue eigenvectors are annihilated by $C$.
 \end{proof}

